create temporary view   user_exp_result_${grass_region_without_quote}
as
select  user_id
        ,COLLECT_SET(exp_group_id) as exp_group_ids
from    (
    select  user_id
            ,exp_group_id
    from    srdi_mart.dim_sr_data_warehouse_abtest_user_group
    where   grass_region in (${grass_region})
      and   local_date = ${local_date}
      and   is_assignment_log = 1
      and   is_homepage_whitelist = 1

    union all

    select  user_id
            ,t1.exp_group_id
    from    (
        select  user_id
                ,exp_group_id
        from    srdi_mart.dim_sr_data_warehouse_abtest_user_group
        where   grass_region in (${grass_region})
          and   local_date = ${local_date}
          and   is_assignment_log = 1
    ) t1
    inner join exp_filter_homepage_other_result_${grass_region_without_quote} as t2
    on      t1.exp_group_id = t2.exp_group_id
)
group by 1
;

