create temporary view  user_union_all_data_${grass_region_without_quote} as
select  user_id
        ,user_purchase_type
        ,platform
        ,app_version_prefix
        ,card_type
        ,is_ads
        ,imp_cnt
        ,click_cnt
        ,order_cnt
        ,gmv
        ,pc2_gmv
        ,location
        ,ppv_cnt
        ,minippv_cnt
        ,vv
        ,self_duration
        ,landing_page_duration
        ,pdp_page_duration
        ,internal_scroll_depth
        ,total_duration
        ,0 as ads_revenue
        ,0 as ads_narrow_gmv
        ,0 as ads_broad_gmv
        ,0 as ads_item_gmv
        ,0 as ads_narrow_order_cnt
        ,0 as ads_broad_order_cnt
        ,0 as ads_item_order_cnt
from    user_cardtype_ad_data_${grass_region_without_quote}
union all
select  T1.user_id
        ,T2.user_purchase_type
        ,T2.platform
        ,T2.app_version_prefix
        ,'__ALL__' as card_type
        ,T1.is_ads
        ,0 as imp_cnt
        ,0 as click_cnt
        ,0 as order_cnt
        ,0 as gmv
        ,0 as pc2_gmv
        ,0 as location
        ,0 as ppv_cnt
        ,0 as minippv_cnt
        ,0 as vv
        ,0 as self_duration
        ,0 as landing_page_duration
        ,0 as pdp_page_duration
        ,0 as internal_scroll_depth
        ,0 as total_duration
        ,T1.ads_revenue
        ,T1.ads_narrow_gmv
        ,T1.ads_broad_gmv
        ,T1.ads_item_gmv
        ,T1.ads_narrow_order_cnt
        ,T1.ads_broad_order_cnt
        ,T1.ads_item_order_cnt
from    (
    select  user_id
            ,sum(ads_revenue_usd) as ads_revenue
            ,sum(ads_gmv_usd) as ads_narrow_gmv
            ,sum(ads_broad_gmv_usd) as ads_broad_gmv
            ,sum(if(if_ads_item = 1, omni_gmv_usd, 0)) as ads_item_gmv
            ,sum(ads_direct_order_cnt) as ads_narrow_order_cnt
            ,sum(ads_broad_order_cnt) as ads_broad_order_cnt
            ,sum(if(if_ads_item = 1, omni_order_cnt, 0)) as ads_item_order_cnt
            ,1 as is_ads
    from    mp_paidads.dws_advertise_user_exp_common_feature_performance_1d__reg_s0_live
    where   tz_type = 'local'
      and   grass_region = ${grass_region}
      and   grass_date = ${local_date}
      and   common_feature = 'Daily Discover'
    group by user_id
) as T1
left join (
    select  user_id
            ,platform
            ,app_version_prefix
            ,user_purchase_type
    from    srdi_mart.dim_sr_data_warehouse_user_label
    where   grass_region = ${grass_region}
      and   local_date = ${local_date}
) as T2
on      T1.user_id = T2.user_id
;

